use CardPay\Services\SmsParserService;
use CardPay\Services\SmsService;
use CardPay\Services\TokenAllocator;
use CardPay\Services\UploadService;
use CardPay\Services\WebhookService;

$root=dirname(__DIR__);Env::load($root.'/.env');
$config=new Config(['app'=>['name'=>Env::get('APP_NAME','CardPay'),'env'=>Env::get('APP_ENV','production'),'debug'=>(bool)Env::get('APP_DEBUG',false),'url'=>Env::get('APP_URL',''),'timezone'=>Env::get('APP_TIMEZONE','Asia/Tehran'),'locale'=>Env::get('APP_LOCALE','fa'),'currency'=>'IRR'],'db'=>['connection'=>Env::get('DB_CONNECTION','mysql'),'host'=>Env::get('DB_HOST','127.0.0.1'),'port'=>(int)Env::get('DB_PORT',3306),'database'=>Env::get('DB_DATABASE',''),'username'=>Env::get('DB_USERNAME',''),'password'=>Env::get('DB_PASSWORD',''),'prefix'=>Env::get('DB_PREFIX','cp_')],'security'=>['api_timestamp_tolerance'=>(int)Env::get('API_TIMESTAMP_TOLERANCE',300),'api_rate_limit'=>(int)Env::get('API_RATE_LIMIT',120),'device_rate_limit'=>(int)Env::get('DEVICE_RATE_LIMIT',60),'login_rate_limit'=>(int)Env::get('LOGIN_RATE_LIMIT',5)],'payment'=>['token_cooldown_minutes'=>10],'upload'=>['max_mb'=>(int)Env::get('UPLOAD_MAX_MB',5)]]);
date_default_timezone_set((string)$config->get('app.timezone','UTC'));
$dsn=$config->get('db.connection')==='sqlite'?'sqlite:'.$config->get('db.database'):sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config->get('db.host'),$config->get('db.port'),$config->get('db.database'));
$pdo=new PDO($dsn,$config->get('db.connection')==='sqlite'?null:$config->get('db.username'),$config->get('db.connection')==='sqlite'?null:$config->get('db.password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$db=new Database($pdo,(string)$config->get('db.prefix','cp_'));$settings=new SettingsRepository($db);$stored=$settings->all();
foreach(['app_name'=>'app.name','currency'=>'app.currency','timezone'=>'app.timezone','locale'=>'app.locale','token_cooldown_minutes'=>'payment.token_cooldown_minutes'] as$key=>$path)if(array_key_exists($key,$stored))$config->set($path,$stored[$key]);
date_default_timezone_set((string)$config->get('app.timezone','UTC'));
$container=new Container();$session=new Session();$crypto=new Crypto((string)Env::get('APP_KEY'));
$container->set(Config::class,$config);$container->set(Database::class,$db);$container->set(Session::class,$session);$container->set(Csrf::class,new Csrf($session));$container->set(Crypto::class,$crypto);$container->set(View::class,new View($root.'/app/Views'));$container->set(Logger::class,new Logger($root.'/storage/logs/cardpay.log'));$container->set(SettingsRepository::class,$settings);
$container->set(ApplicationRepository::class,fn()=>new ApplicationRepository($db,$crypto));$container->set(CardRepository::class,fn()=>new CardRepository($db,$crypto));$container->set(DeviceRepository::class,fn()=>new DeviceRepository($db,$crypto));$container->set(PaymentRepository::class,fn()=>new PaymentRepository($db));
$container->set(PaymentStateMachine::class,new PaymentStateMachine());$container->set(TokenAllocator::class,fn()=>new TokenAllocator($db));$container->set(AmountNormalizer::class,new AmountNormalizer());$container->set(SmsParserService::class,fn(Container$c)=>new SmsParserService($c->get(AmountNormalizer::class)));$container->set(RateLimiter::class,fn()=>new RateLimiter($db));$container->set(AuditService::class,fn()=>new AuditService($db));$container->set(WebhookService::class,fn()=>new WebhookService($db,$crypto));
$container->set(PaymentService::class,fn(Container$c)=>new PaymentService($db,$c->get(CardRepository::class),$c->get(PaymentRepository::class),$c->get(TokenAllocator::class),$c->get(PaymentStateMachine::class),$c->get(WebhookService::class),$config));
$container->set(ExpirationService::class,fn(Container$c)=>new ExpirationService($db,$c->get(PaymentRepository::class),$c->get(TokenAllocator::class),$c->get(WebhookService::class),$config));
$container->set(MaintenanceService::class,fn(Container$c)=>new MaintenanceService($db,$c->get(ExpirationService::class),$c->get(TokenAllocator::class),$c->get(WebhookService::class)));
$container->set(ApiAuthService::class,fn(Container$c)=>new ApiAuthService($db,$c->get(ApplicationRepository::class),$crypto,$config));$container->set(DeviceAuthService::class,fn(Container$c)=>new DeviceAuthService($db,$c->get(DeviceRepository::class),$crypto,$config));
$container->set(SmsService::class,fn(Container$c)=>new SmsService($db,$c->get(DeviceRepository::class),$c->get(PaymentRepository::class),$c->get(SmsParserService::class),$c->get(PaymentStateMachine::class),$c->get(TokenAllocator::class),$c->get(WebhookService::class),$c->get(ExpirationService::class),$config));
$container->set(ManualReviewService::class,fn(Container$c)=>new ManualReviewService($db,$c->get(PaymentRepository::class),$c->get(PaymentStateMachine::class),$c->get(TokenAllocator::class),$c->get(WebhookService::class),$config));
$container->set(UploadService::class,new UploadService($root,$config));
$container->set(AdminService::class,fn(Container$c)=>new AdminService($db,$c->get(ApplicationRepository::class),$c->get(CardRepository::class),$c->get(DeviceRepository::class),$c->get(PaymentRepository::class),$settings,$crypto,$c->get(SmsParserService::class),$c->get(AuditService::class)));
$registry=new DriverRegistry();$registry->register(new CardTransferDriver());$container->set(DriverRegistry::class,$registry);
return$container;
